function maxArea(height) {
  let maxWater = 0, left = 0, right = height.length - 1;
  while (left < right) {
    const width = right - left;
    const h = Math.min(height[left], height[right]);
    maxWater = Math.max(maxWater, width * h);
    if (height[left] < height[right]) left++;
    else right--;
  }
  return maxWater;
}
```
O(N) Time, O(1) Space.
